import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != actor);
        address owner0 = address(0);
        vm.prank(owner0);
        c.transferOwnership(actor);
        vm.prank(actor);
        c.owned();
        vm.prank(actor);
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner && c.owner() != actor);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address target) public {
        // keep the domain wide: any non-zero actor other than the deployer,
        // and any non-zero target distinct from the actor
        vm.assume(actor != address(0));
        vm.assume(target != address(0));
        vm.assume(actor != address(this));
        vm.assume(target != actor);

        // hand ownership to the fuzzed actor through the only public path
        vm.prank(address(this));
        c.transferOwnership(actor);

        // the fuzzed owner performs a guarded ownership transfer
        vm.prank(actor);
        c.transferOwnership(target);

        // general rule: after the owner's transferOwnership(target), owner == target.
        // The mutant writes owner = msg.sender inside the modifier on every guarded call,
        // so for some (actor, target) the guarded call leaves owner elsewhere than target.
        assertTrue(c.owner() == target);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address n, address s) public {
        vm.assume(a != address(0));
        vm.assume(n != a);
        vm.assume(s != n);

        // owner starts at address(0); set initial owner to a through the public surface
        vm.prank(address(0));
        c.transferOwnership(a);

        // current owner a transfers ownership to n
        vm.prank(a);
        c.transferOwnership(n);

        // Rule: after transferring ownership to n, a call from unrelated party s (s != n)
        // to the guarded function owned() must revert — guarded calls must not confer
        // ownership or mutate owner as a side effect.
        bool ok;
        vm.prank(s);
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

