pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address n) public {
        vm.assume(a != address(0));
        vm.assume(n != address(0));
        // The test contract is the deployer, hence current owner: hand ownership to fuzzed actor a.
        c.transferOwnership(a);
        // Actor a performs the guarded transfer to fuzzed target n.
        vm.prank(a);
        c.transferOwnership(n);
        // The guarded transfer's explicit assignment must be the final writer of owner.
        assertTrue(c.owner() == n);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // The only admissible caller of owned() is the current owner;
        // owner defaults to address(0) since it is never initialized.
        vm.assume(actor == c.owner());
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
